// Generates one thin route file per page & language from src/lib/routes.ts, so every page
// ships only its own view's CSS/JS (a single catch-all route would bundle the whole site).
// Run automatically before dev/build. Generated files are marked and fully overwritten.
import { readFileSync, writeFileSync, mkdirSync, rmSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const pages = join(root, 'src', 'pages');
const MARK = '// @generated by scripts/gen-routes.mjs — do not edit';

const src = readFileSync(join(root, 'src/lib/routes.ts'), 'utf8');
const body = src.slice(src.indexOf('export const ROUTES'), src.indexOf('} as const'));
const routes = [...body.matchAll(/^\s+(\w+):\s*\{\s*tr:\s*'([^']+)',\s*en:\s*'([^']+)',\s*ar:\s*'([^']+)'\s*\}/gm)].map((m) => ({ key: m[1], tr: m[2], en: m[3], ar: m[4] }));
const viewsSrc = readFileSync(join(root, 'src/views/index.ts'), 'utf8');
const viewOf = Object.fromEntries([...viewsSrc.matchAll(/(\w+):\s*(\w+)[,\s]/g)].filter(([, k]) => routes.some((r) => r.key === k)).map(([, k, v]) => [k, v]));
const dynamic = {
  line: `lines.map((l) => ({ params: { slug: l.slug } }))`,
  machine: `allModels.filter((m: any) => m.slug).map((m: any) => ({ params: { slug: m.slug } }))`,
  note: `postsSorted.map((p) => ({ params: { slug: p.slug } }))`,
};

// remove previously generated files
const walk = (d) => readdirSync(d).flatMap((f) => { const p = join(d, f); return statSync(p).isDirectory() ? walk(p) : [p]; });
if (existsSync(pages)) for (const f of walk(pages)) if (readFileSync(f, 'utf8').includes(MARK)) rmSync(f);

let n = 0;
for (const r of routes) {
  const View = viewOf[r.key];
  if (!View) continue;
  for (const lang of ['tr', 'en', 'ar']) {
    const p = r[lang];
    let file = p === '/' ? 'index.astro' : p.replace(/^\//, '').replace(/\/$/, '/index').replace(':slug', '[slug]') + (p.endsWith('/') ? '.astro' : '.astro');
    if (p.endsWith('/') && p !== '/') file = p.replace(/^\//, '') + 'index.astro';
    const out = join(pages, file);
    mkdirSync(dirname(out), { recursive: true });
    const rel = relative(dirname(out), join(root, 'src')).replace(/\\/g, '/');
    const dyn = dynamic[r.key];
    const code = `---
${MARK}
import View from '${rel}/views/${View}.astro';
${dyn ? `import { lines, allModels, postsSorted } from '${rel}/lib/data';
export function getStaticPaths() { return ${dyn}; }
const { slug } = Astro.params;` : 'const slug = undefined;'}
---
<View lang="${lang}" slug={slug} />
`;
    writeFileSync(out, code);
    n++;
  }
}
console.log(`routes: ${n} files`);
